#include &lt;signal.h&gt;
#include &lt;unistd.h&gt;
#include &lt;string.h&gt;

volatile sig_atomic_t running = 1;

void handler(int sig) {
    if (sig == SIGUSR1) {
        /* Sinyal handler'da printf tehlikeli; write() kullan */
        const char msg[] = "SIGUSR1 alındı\n";
        write(STDOUT_FILENO, msg, sizeof(msg) - 1);
    } else if (sig == SIGTERM) {
        running = 0;
    }
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = handler;
    sigemptyset(&amp;sa.sa_mask);
    sigaction(SIGUSR1, &amp;sa, NULL);
    sigaction(SIGTERM, &amp;sa, NULL);

    printf("PID: %d\n", getpid());
    while (running) {
        pause();    /* Sinyali bekle */
    }
    puts("Temiz çıkış");
    return 0;
}
</code></pre> <pre><code># Başka terminalden:
kill -SIGUSR1 &lt;PID&gt;
kill -SIGTERM &lt;PID&gt;
</code></pre> <p>Sinyal Handler Güvenliği</p> <p>Sinyal handler'ların içinde yalnızca async-signal-safe fonksiyonlar çağrılabilir. <code>printf</code>, <code>malloc</code>, <code>free</code> güvenli değildir - bunları handler içinde çağırmak tanımsız davranışa yol açar. Bunun yerine global bir bayrak (<code>sig_atomic_t</code>) set edip ana döngüde işleyin.</p>

